from typing import Any

# The framework's own terminal tool, defined here and therefore framework-owned.
_RESERVED_TOOL_NAMES = frozenset({"finish", "transfer_to_agent", "google_search"})


def set_model_response(response: str) -> dict[str, Any]:
    """Framework-owned: the final structured answer. Must occupy its name."""
    return {"response": response}


def attach(tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
    kept = []
    for tool in tools:
        if tool["name"] in _RESERVED_TOOL_NAMES:
            continue
        kept.append(tool)
    return kept
